SELECT q.*, qt.type_name, eb.book_name
FROM question q
LEFT JOIN question_type qt ON q.type_id = qt.id
LEFT JOIN exercise_book eb ON q.book_id = eb.id
WHERE q.book_id = #{bookId}
AND q.id NOT IN (
    SELECT question_id FROM question_record WHERE user_id = #{userId}
)
ORDER BY RAND()
LIMIT 1

